mapper.select:
SELECT

FROM shop_delivery_rider r

    r.is_deleted = 0


        AND r.logistics_company_id = #{q.logisticsCompanyId}


        AND r.vehicle_type = #{q.vehicleType}


        AND r.online_status = #{q.onlineStatus}


        AND r.work_status = #{q.workStatus}


        AND r.status = #{q.status}



        AND (r.rider_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR r.rider_code LIKE CONCAT('%', #{q.keyword}, '%')
        OR r.phone LIKE CONCAT('%', #{q.keyword}, '%'))



ORDER BY r.status DESC, r.id DESC
